bands=['VH','VV']
def month(p): return int(dates[p][5:7])
def rmse(a,b): return math.sqrt(sum((x-y)**2 for x,y in zip(a,b))/len(a))

def clim_offset(tr,tp,b,win=6):
    bym=defaultdict(list)
    for p in tr: bym[month(p)].append(data[b][p])
    clim={m:sum(v)/len(v) for m,v in bym.items()}
    off=sum(data[b][p]-clim[month(p)] for p in tr[-win:])/win
    return [clim[month(p)]+off for p in tp]

def clim_only(tr,tp,b):
    bym=defaultdict(list)
    for p in tr: bym[month(p)].append(data[b][p])
    clim={m:sum(v)/len(v) for m,v in bym.items()}
    return [clim[month(p)] for p in tp]

# harmonic regression with trend
def harmonic(tr,tp,b,K=2):
    import math as M
    n=len(tr)
    def feats(i):
        t=i/29.0
        f=[1.0,t]
        for k in range(1,K+1):
            f.append(M.sin(2*M.pi*k*t)); f.append(M.cos(2*M.pi*k*t))
        return f
    X=[feats(i) for i in range(n)]
    y=[data[b][p] for p in tr]
    # normal equations
    m=len(X[0])
    A=[[sum(X[i][a]*X[i][c] for i in range(n)) for c in range(m)] for a in range(m)]
    Bv=[sum(X[i][a]*y[i] for i in range(n)) for a in range(m)]
    # gaussian elim
    for c in range(m):
        piv=max(range(c,m),key=lambda r:abs(A[r][c])); A[c],A[piv]=A[piv],A[c]; Bv[c],Bv[piv]=Bv[piv],Bv[c]
        for r in range(m):
