                f=A[r][c]/A[c][c]
                for k in range(c,m): A[r][k]-=f*A[c][k]
                Bv[r]-=f*Bv[c]
    coef=[Bv[i]/A[i][i] for i in range(m)]
    out=[]
    for j in range(len(tp)):
        f=feats(n+j); out.append(sum(f[k]*coef[k] for k in range(m)))
    return out

folds=[(order[:i],order[i:i+27]) for i in range(len(order)-27, 60, -13)]
for b in bands:
