    Xty=[sum(X[k][i]*y[k] for k in range(len(X))) for i in range(n)]
    A=[row[:]+[Xty[i]] for i,row in enumerate(XtX)]
    for c in range(n):
        piv=max(range(c,n),key=lambda r:abs(A[r][c])); A[c],A[piv]=A[piv],A[c]
        if abs(A[c][c])<1e-12: continue
