import csv, math
from collections import defaultdict
from datetime import datetime

rows = list(csv.DictReader(open("data.csv")))
by_band = defaultdict(list)
for r in rows:
    by_band[r["band"]].append((datetime.strptime(r["date"],"%Y-%m-%d").date(), float(r["y"])))
for b in by_band: by_band[b].sort()
def doy(d): return d.timetuple().tm_yday
def circ(a,b):
    d=abs(a-b); return min(d,365-d)

def clim(series, d, W=10, exclude_year=None):
    cand=[vv for (dd,vv) in series if (exclude_year is None or dd.year!=exclude_year) and circ(doy(dd),doy(d))<=W]
    return sum(cand)/len(cand) if cand else None

for b in by_band:
    series=by_band[b]
    for N in [0,3,5,8,12]:
        errs=[]
        for i,(d,v) in enumerate(series):
            base=clim(series,d,10,exclude_year=d.year)
            if base is None: continue
            if N>0 and i>=N:
                # recent residuals using full climatology (all years) at those points
                res=[]
                for j in range(i-N,i):
                    dd,vv=series[j]
                    c=clim(series,dd,10)
                    if c is not None: res.append(vv-c)
                off=sum(res)/len(res) if res else 0.0
            else:
                off=0.0
            errs.append((base+off-v)**2)
        print(b,"N=%d RMSE=%.3f"%(N,math.sqrt(sum(errs)/len(errs))))
    print()
