import csv, datetime, numpy as np
from collections import defaultdict

rows=list(csv.DictReader(open("data.csv")))
by=defaultdict(dict); dates={}
for r in rows:
    by[r["band"]][r["period_id"]]=float(r["y"]); dates[r["period_id"]]=r["date"]
pids=sorted(by["VH"], key=lambda p: dates[p])
BANDS=["VH","VV","VV-VH"]

def t_of(d):
    return datetime.date.fromisoformat(d).toordinal()

def design(ds, t0, K, trend=True):
    cols=[]
    t=np.array([(t_of(d)-t0)/365.25 for d in ds])
    cols.append(np.ones_like(t))
    if trend: cols.append(t)
    doy=np.array([datetime.date.fromisoformat(d).timetuple().tm_yday for d in ds])
    ang=2*np.pi*doy/365.25
    for k in range(1,K+1):
        cols.append(np.sin(k*ang)); cols.append(np.cos(k*ang))
    return np.column_stack(cols)

def fit_predict(train_pids, test_dates, K, trend=True, ridge=1e-6):
    t0=t_of(dates[train_pids[0]])
    Xtr=design([dates[p] for p in train_pids], t0, K, trend)
    Xte=design(test_dates, t0, K, trend)
    out={}
    for b in BANDS:
        y=np.array([by[b][p] for p in train_pids])
        A=Xtr.T@Xtr + ridge*np.eye(Xtr.shape[1])
        w=np.linalg.solve(A, Xtr.T@y)
        out[b]=Xte@w
    return out

# holdout: train before 2023-09-21, test the last ~1 year
cut="2023-09-21"
train=[p for p in pids if dates[p]<cut]
test=[p for p in pids if dates[p]>=cut]
print("train",len(train),"test",len(test))
for K in [1,2,3,4]:
    for trend in [True,False]:
        pred=fit_predict(train,[dates[p] for p in test],K,trend)
        errs={}
        for b in BANDS:
            act=np.array([by[b][p] for p in test])
            errs[b]=round(float(np.sqrt(np.mean((pred[b]-act)**2))),3)
        print(f"K={K} trend={trend}", errs)
