    # for each test date, average train obs within +/-win days of year, with linear trend correction
    out={b:[] for b in BANDS}
    # global trend slope per band from train
    tt=np.array([t_of(dates[p]) for p in train]); tt=(tt-tt.mean())/365.25
    slopes={}
    for b in BANDS:
