def fit_predict(train_periods, test_periods, b, model):
    v={p:series[b][p] for p in train_periods}
    m=sum(v.values())/len(v)
    preds={}
    if model=="persist":
        last=v[train_periods[-1]]
        for p in test_periods: preds[p]=last
    elif model=="clim":
        mm=defaultdict(list)
        for p in train_periods: mm[month(dates[p])].append(v[p])
        for p in test_periods: preds[p]=sum(mm[month(dates[p])])/len(mm[month(dates[p])])
    elif model=="trend":
        xs=list(range(len(train_periods))); xm=sum(xs)/len(xs)
        slope=sum((xs[i]-xm)*(v[train_periods[i]]-m) for i in range(len(xs)))/sum((x-xm)**2 for x in xs)
        for j,p in enumerate(test_periods): preds[p]=m+slope*(len(train_periods)+j-xm)
    elif model=="clim+trend":
        mm=defaultdict(list)
        for p in train_periods: mm[month(dates[p])].append(v[p])
        xs=list(range(len(train_periods))); xm=sum(xs)/len(xs)
