import csv, datetime, math
from collections import defaultdict
rows = list(csv.DictReader(open("data.csv", encoding="utf-8")))
periods=[]; seen=set()
for r in rows:
    if r["period_id"] not in seen: seen.add(r["period_id"]); periods.append(r["period_id"])
dates={r["period_id"]:r["date"] for r in rows}
series=defaultdict(dict)
for r in rows: series[r["band"]][r["period_id"]]=float(r["y"])
def doy(d): return datetime.date.fromisoformat(d).timetuple().tm_yday

def solve(A,y):
    # normal equations, small
    n=len(A[0])
    AtA=[[sum(A[k][i]*A[k][j] for k in range(len(A))) for j in range(n)] for i in range(n)]
    Aty=[sum(A[k][i]*y[k] for k in range(len(A))) for i in range(n)]
    # gaussian elim
    M=[AtA[i][:]+[Aty[i]] for i in range(n)]
    for c in range(n):
        piv=max(range(c,n),key=lambda r:abs(M[r][c])); M[c],M[piv]=M[piv],M[c]
        if abs(M[c][c])<1e-12: continue
        for r in range(n):
            if r!=c:
                f=M[r][c]/M[c][c]
                for k in range(c,n+1): M[r][k]-=f*M[c][k]
    return [M[i][n]/M[i][i] if abs(M[i][i])>1e-12 else 0 for i in range(n)]

def harm_pred(train,test,b,K):
    A=[];y=[]
    for p in train:
        t=2*math.pi*doy(dates[p])/365.25
        row=[1.0]
        for k in range(1,K+1): row+=[math.cos(k*t),math.sin(k*t)]
        A.append(row); y.append(series[b][p])
    coef=solve(A,y)
    out={}
    for p in test:
        t=2*math.pi*doy(dates[p])/365.25
        row=[1.0]
        for k in range(1,K+1): row+=[math.cos(k*t),math.sin(k*t)]
        out[p]=sum(c*r for c,r in zip(coef,row))
    return out

def clim_offset(train,test,b,offset_n):
    mm=defaultdict(list)
    for p in train: mm[int(dates[p][5:7])].append(series[b][p])
    clim={mo:sum(v)/len(v) for mo,v in mm.items()}
    # recent offset: mean of last offset_n residuals from clim
    res=[series[b][p]-clim[int(dates[p][5:7])] for p in train[-offset_n:]]
    off=sum(res)/len(res)
    return {p:clim[int(dates[p][5:7])]+off for p in test}

