import csv, math
from collections import defaultdict
from datetime import date
rows=list(csv.DictReader(open("data.csv")))
data=defaultdict(dict); dates={}
for r in rows:
    data[r["band"]][r["period_id"]]=float(r["y"]); dates[r["period_id"]]=r["date"]
periods=sorted(dates,key=lambda p:dates[p])
d0=date.fromisoformat(dates[periods[0]])
def doy(p): return (date.fromisoformat(dates[p])-d0).days  # days since start

# Build arrays
bands=["VH","VV","VV-VH"]
X={b:[] for b in bands}; T={b:[] for b in bands}
for b in bands:
    for p in periods:
        X[b].append(data[b][p]); T[b].append(doy(p))

def design(t, trend=True, K=2):
    # t in days; annual period 365.25
    row=[1.0]
    for k in range(1,K+1):
        row.append(math.sin(2*math.pi*k*t/365.25))
        row.append(math.cos(2*math.pi*k*t/365.25))
    if trend: row.append(t/365.25)
    return row

def solve(A,y):
    # normal equations
    n=len(A[0])
    AtA=[[sum(A[i][a]*A[i][b] for i in range(len(A))) for b in range(n)] for a in range(n)]
    Aty=[sum(A[i][a]*y[i] for i in range(len(A))) for a in range(n)]
    # gaussian elim
    M=[AtA[i][:]+[Aty[i]] for i in range(n)]
    for c in range(n):
        piv=max(range(c,n),key=lambda r:abs(M[r][c]))
        M[c],M[piv]=M[piv],M[c]
        pv=M[c][c]
        for j in range(c,n+1): M[c][j]/=pv
        for r in range(n):
            if r!=c and M[r][c]!=0:
                f=M[r][c]
                for j in range(c,n+1): M[r][j]-=f*M[c][j]
    return [M[i][n] for i in range(n)]

def predict(coef,t,trend=True,K=2):
    row=design(t,trend,K)
    return sum(c*x for c,x in zip(coef,row))

# Backtest: train on all but last 27 periods, predict last 27
for trend in [True,False]:
  for K in [1,2,3]:
    errs={b:[] for b in bands}
    ntr=len(periods)-27
    for b in bands:
        A=[design(T[b][i],trend,K) for i in range(ntr)]
        y=X[b][:ntr]
        coef=solve(A,y)
        for i in range(ntr,len(periods)):
            pr=predict(coef,T[b][i],trend,K)
            errs[b].append(pr-X[b][i])
    rmse={b:math.sqrt(sum(e*e for e in errs[b])/len(errs[b])) for b in bands}
    print("trend=%s K=%d"%(trend,K), {b:round(rmse[b],3) for b in bands})
