import csv, datetime, statistics, math
from collections import defaultdict
rows=list(csv.DictReader(open("data.csv")))
data=defaultdict(dict); dates={}
for r in rows:
    data[r["band"]][r["period_id"]]=float(r["y"]); dates[r["period_id"]]=r["date"]
order=sorted(dates,key=lambda p:dates[p])
D={b:[data[b][p] for p in order] for b in data}
DT=[datetime.date.fromisoformat(dates[p]) for p in order]

def interp_at(series, dts, target):
    # linear interp of series at target date
    if target<=dts[0]: return series[0]
    if target>=dts[-1]: return series[-1]
    for i in range(len(dts)-1):
        if dts[i]<=target<=dts[i+1]:
            f=(target-dts[i]).days/(dts[i+1]-dts[i]).days
            return series[i]+f*(series[i+1]-series[i])

def seasonal_naive(series,dts,target):
    # value at same date one year earlier, interpolated
    try: t2=target.replace(year=target.year-1)
    except: t2=target.replace(year=target.year-1,day=28)
    return interp_at(series,dts,t2)

def climatology(series,dts,target):
    # mean of same-day-of-year across all years, interpolated
    vals=[]
    for y in range(dts[0].year,dts[-1].year+1):
        try: t2=target.replace(year=y)
        except: t2=target.replace(year=y,day=28)
        if dts[0]<=t2<=dts[-1]: vals.append(interp_at(series,dts,t2))
    return statistics.mean(vals) if vals else series[-1]

def blend(series,dts,target):
    a=seasonal_naive(series,dts,target); b=climatology(series,dts,target)
    return 0.5*a+0.5*b

def drift(series,dts,target):
    # seasonal naive + linear trend from last year
    sn=seasonal_naive(series,dts,target)
    # trend: mean of last 12 minus mean of previous 12
    if len(series)>=24:
        tr=(statistics.mean(series[-12:])-statistics.mean(series[-24:-12]))
        yrs=(target-dts[-1]).days/365.25
        return sn+tr*yrs
    return sn

methods={"snaive":seasonal_naive,"clim":climatology,"blend":blend,"drift":drift}
H=27
for name,fn in methods.items():
    tot=0;n=0;per={}
    for b in D:
        s=D[b]; errs=[]
        for i in range(len(s)-H,len(s)):
            pred=fn(s[:i],DT[:i],DT[i])
            errs.append((pred-s[i])**2)
        per[b]=math.sqrt(statistics.mean(errs)); tot+=sum(errs); n+=len(errs)
    print(name, "RMSE", round(math.sqrt(tot/n),4), {b:round(v,3) for b,v in per.items()})
