def design(doy,t,K,trend):
    x=[1.0]
    if trend: x.append(t)
    for k in range(1,K+1):
        x.append(math.cos(2*math.pi*k*doy/365.25)); x.append(math.sin(2*math.pi*k*doy/365.25))
    return x

def solve(A,b):
    n=len(A); m=len(A[0])
    M=[[sum(A[i][r]*A[i][c] for i in range(n)) for c in range(m)] for r in range(m)]
    v=[sum(A[i][r]*b[i] for i in range(n)) for r in range(m)]
    for r in range(m): M[r][r]+=1e-9
    for c in range(m):
        p=max(range(c,m),key=lambda r:abs(M[r][c]))
        M[c],M[p]=M[p],M[c]; v[c],v[p]=v[p],v[c]
        if abs(M[c][c])<1e-12: continue
        for r in range(m):
            if r!=c:
                f=M[r][c]/M[c][c]
                for k in range(c,m): M[r][k]-=f*M[c][k]
                v[r]-=f*v[c]
    return [v[i]/M[i][i] if abs(M[i][i])>1e-12 else 0.0 for i in range(m)]

def fit(pts,K,trend,robust=True):
    t0=pts[0][0]
    A=[];b=[]
    for dt,doy,y in pts:
        A.append(design(doy,(dt-t0).days/365.25,K,trend)); b.append(y)
    w=[1.0]*len(b); coef=None
    for it in range(10 if robust else 1):
        Aw=[[A[i][j]*math.sqrt(w[i]) for j in range(len(A[0]))] for i in range(len(A))]
        bw=[b[i]*math.sqrt(w[i]) for i in range(len(b))]
        coef=solve(Aw,bw)
        res=[b[i]-sum(A[i][j]*coef[j] for j in range(len(coef))) for i in range(len(b))]
        med=sorted(res)[len(res)//2]
