        w=[1.0 if abs(r-med)<=2.0*mad else (2.0*mad/abs(r-med)) for r in res]
    return coef,t0

def pred(coef,t0,dt,doy,K,trend):
    return sum(c*x for c,x in zip(coef,design(doy,(dt-t0).days/365.25,K,trend)))

