series={}
for r in rows:
    series.setdefault(r["band"],{})[r["period_id"]]=float(r["y"])
bands=sorted(series)

def interp_daily(band):
    # build sorted (ordinal, value) and linear interp function
    pts=sorted((dates[p].toordinal(), series[band][p]) for p in periods)
    xs=[a for a,b in pts]; ys=[b for a,b in pts]
    def f(ordn):
        if ordn<=xs[0]: return ys[0]
        if ordn>=xs[-1]: return ys[-1]
        # binary search
        import bisect
        i=bisect.bisect_right(xs,ordn)-1
        x0,x1=xs[i],xs[i+1]; y0,y1=ys[i],ys[i+1]
        t=(ordn-x0)/(x1-x0)
        return y0+t*(y1-y0)
    return f

# backtest: train cutoff 2023-09-22, predict 2023-10-01..2024-09-22
cut=datetime.date(2023,9,22).toordinal()
def doy(d): return d.timetuple().tm_yday

def predict_seasonal(band, target_ord, train_ords, weight_mode="equal"):
    f=interp_daily(band)
    td=datetime.date.fromordinal(target_ord)
    ty=td.year; tday=doy(td)
    vals=[]
    for y in range(2020, ty):
        # same doy in year y
        try: d=datetime.date(y,td.month,td.day)
        except: d=datetime.date(y,td.month,28)
        o=d.toordinal()
        if o>cut: continue
        vals.append((y,f(o)))
    if not vals: return None
    if weight_mode=="equal":
        return sum(v for _,v in vals)/len(vals)
    else:
        # recent weighted
        w=[0.5**(ty-y) for y,_ in vals]
        return sum(wi*v for wi,(_,v) in zip(w,vals))/sum(w)

# evaluate on actual points in holdout
hold=[p for p in periods if dates[p].toordinal()>cut]
print("holdout n",len(hold))
for wm in ["equal","recent"]:
    print("=== weight",wm)
    for b in bands:
